<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { activeWorkshops, listCustomers } from '../services/customers'
import { checkVehicleVin, createVehicle, uploadVehiclePhotos } from '../services/vehicles'
import type { Customer, Workshop } from '../types'
const route=useRoute();const workshops=ref<Workshop[]>([]);const customers=ref<Customer[]>([]);const workshopId=ref<number|null>(route.query.workshop_id?Number(route.query.workshop_id):null);const customerId=ref<number|null>(route.query.customer_id?Number(route.query.customer_id):null);const vin=ref('');const make=ref('');const model=ref('');const year=ref(new Date().getFullYear());const plate=ref('');const files=ref<File[]>([]);const previews=ref<string[]>([]);const saving=ref(false);const checkingVin=ref(false);const duplicateVin=ref(false);const error=ref('');const notice=ref('')
const valid=computed(()=>!!workshopId.value&&!!customerId.value&&/^[A-HJ-NPR-Z0-9]{17}$/.test(vin.value)&&!duplicateVin.value&&make.value.trim().length>=2&&model.value.trim().length>0&&year.value>=1886&&year.value<=2100)
async function loadCustomers(){customers.value=workshopId.value?await listCustomers({workshop_id:workshopId.value,status_filter:'activos'}):[];if(customerId.value&&!customers.value.some(x=>x.id===customerId.value))customerId.value=null}
async function verifyVin(){duplicateVin.value=false;if(!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin.value))return;checkingVin.value=true;try{duplicateVin.value=(await checkVehicleVin(vin.value)).duplicate}catch{error.value='No fue posible comprobar el VIN.'}finally{checkingVin.value=false}}
function onFiles(event:Event){error.value='';const selected=Array.from((event.target as HTMLInputElement).files||[]);for(const file of selected){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){error.value='Las fotos deben ser JPG, PNG o WebP.';return}if(file.size>15*1024*1024){error.value=`${file.name} supera el límite de 15 MB.`;return}}files.value=[...files.value,...selected];previews.value=files.value.map(file=>URL.createObjectURL(file));(event.target as HTMLInputElement).value=''}
function removePhoto(index:number){files.value.splice(index,1);previews.value.splice(index,1)}
async function save(){if(!valid.value||!workshopId.value||!customerId.value)return;saving.value=true;error.value='';try{const vehicle=await createVehicle(workshopId.value,customerId.value,{vin:vin.value,make:make.value,model:model.value,year:year.value,plate:plate.value||null});if(files.value.length)await uploadVehiclePhotos(vehicle.id,files.value);notice.value=`Vehículo ${vehicle.vin} registrado y asociado al cliente.`;vin.value='';make.value='';model.value='';plate.value='';files.value=[];previews.value=[]}catch(c:any){error.value=c.response?.data?.detail||'No fue posible registrar el vehículo.'}finally{saving.value=false}}
onMounted(async()=>{try{workshops.value=await activeWorkshops();await loadCustomers()}catch{error.value='No fue posible cargar talleres o clientes activos.'}})
</script>
<template><v-container class="page-shell"><header class="page-header"><p class="eyebrow">VEHÍCULOS</p><div class="header-row"><div class="header-icon"><v-icon icon="mdi-car-plus" size="27"/></div><div><h1>Registrar vehículo</h1><p class="subtitle">Asocia un vehículo a un cliente activo dentro de su centro automotriz.</p></div></div></header><v-alert v-if="error" type="error" variant="tonal" closable class="mb-5" @click:close="error=''">{{error}}</v-alert><div class="form-grid"><v-card class="module-card" elevation="0"><v-card-text><div class="card-title"><div class="card-icon"><v-icon icon="mdi-account-switch-outline"/></div><div><h2>Asociación</h2><p>Selecciona el centro automotriz y el cliente propietario.</p></div></div><v-divider class="my-5"/><v-row><v-col cols="12"><v-select v-model="workshopId" label="Centro automotriz asociado *" :items="workshops" item-title="name" item-value="id" prepend-inner-icon="mdi-storefront-outline" variant="outlined" density="comfortable" @update:model-value="loadCustomers"/></v-col><v-col cols="12"><v-select v-model="customerId" label="Cliente asociado *" :items="customers" :item-title="(x:Customer)=>`${x.first_name} ${x.paternal_surname}`" item-value="id" prepend-inner-icon="mdi-account-outline" variant="outlined" density="comfortable" :disabled="!workshopId"/></v-col></v-row></v-card-text></v-card><v-card class="module-card" elevation="0"><v-card-text><div class="card-title"><div class="card-icon"><v-icon icon="mdi-car-info"/></div><div><h2>Datos del vehículo</h2><p>El VIN se valida antes de crear la asociación.</p></div></div><v-divider class="my-5"/><v-row><v-col cols="12"><v-text-field :model-value="vin" label="Número de serie (VIN) *" placeholder="Ej. 1HGCM82633A004352" maxlength="17" hint="17 caracteres alfanuméricos; sin I, O ni Q" persistent-hint prepend-inner-icon="mdi-barcode" variant="outlined" density="comfortable" @update:model-value="vin=String($event).toUpperCase().replace(/[^A-Z0-9]/g,'')"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="make" label="Marca *" placeholder="Ej. Honda" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="model" label="Modelo *" placeholder="Ej. Civic" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model.number="year" label="Año *" placeholder="Ej. 2024" type="number" variant="outlined" density="comfortable"/></v-col><v-col cols="12" md="6"><v-text-field v-model.trim="plate" label="Placas (opcional)" placeholder="Ej. ABC-123-A" variant="outlined" density="comfortable"/></v-col></v-row></v-card-text></v-card></div><footer class="action-footer"><p>Se comprobará que el VIN no exista previamente en el sistema.</p><v-btn color="primary" size="large" prepend-icon="mdi-car-plus" :disabled="!valid" :loading="saving" @click="save">Registrar vehículo</v-btn></footer><v-snackbar :model-value="!!notice" color="success" @update:model-value="notice=''">{{notice}}</v-snackbar></v-container></template>
<style scoped>.page-shell{max-width:1120px;padding:38px 32px 64px}.page-header{margin-bottom:28px}.header-row,.card-title{display:flex;gap:14px;align-items:flex-start}.header-icon,.card-icon{display:grid;place-items:center;flex:none;border-radius:12px;background:#edf3ff;color:#3867de}.header-icon{width:52px;height:52px}.card-icon{width:42px;height:42px}.eyebrow{margin:0 0 8px;color:#3364a2;font-weight:800;letter-spacing:1.3px;font-size:.72rem}.page-header h1{margin:0;color:#172b4d;font-size:clamp(1.8rem,2.6vw,2.3rem);line-height:1.15;font-weight:800}.subtitle,.card-title p{margin:5px 0 0;color:#66758b;font-size:.88rem}.form-grid{display:grid;grid-template-columns:.9fr 1.15fr;gap:24px;align-items:start}.module-card,.action-footer{border:1px solid #e4e9f2;border-radius:16px;background:#fff;box-shadow:0 12px 28px rgba(23,43,77,.05)}.module-card{padding:6px}.card-title h2{margin:0;color:#172b4d;font-size:1.05rem}.action-footer{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:18px 24px;margin-top:24px}.action-footer p{margin:0;color:#748197;font-size:.84rem}.action-footer .v-btn{text-transform:none;font-weight:700;border-radius:11px}@media(max-width:900px){.form-grid{grid-template-columns:1fr}}@media(max-width:600px){.page-shell{padding:24px 16px 42px}.action-footer{align-items:stretch;flex-direction:column;text-align:center}}:global(.v-theme--dark) .module-card,:global(.v-theme--dark) .action-footer{background:#1e3559;border-color:#30496e}:global(.v-theme--dark) .page-header h1,:global(.v-theme--dark) .card-title h2{color:#f4f7ff}:global(.v-theme--dark) .subtitle,:global(.v-theme--dark) .card-title p,:global(.v-theme--dark) .action-footer p{color:#c3d6ea}</style>
